using Microsoft.VisualStudio.TestTools.UnitTesting;
using Store;

namespace Store.Tests;

[TestClass]
public class ShoppingCartTests
{
    private ShoppingCart _cart = null!;

    [TestInitialize]
    public void Setup() => _cart = new ShoppingCart();

    // --- AddItem Tests ---

    [TestMethod]
    [DataRow("SKU-1", 1, 9.99)]
    [DataRow("SKU-2", 5, 2.50)]
    [DataRow("SKU-3", 100, 0.01)]
    public void AddItem_ValidInputs_IncreasesTotal(string sku, int qty, double price)
    {
        _cart.AddItem(sku, qty, (decimal)price);

        Assert.AreEqual((decimal)(qty * price), _cart.CalculateTotal());
    }

    [TestMethod]
    public void AddItem_SameSkuTwice_CombinesQuantity()
    {
        _cart.AddItem("ABC", 2, 10m);
        _cart.AddItem("ABC", 3, 10m);

        Assert.AreEqual(50m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void AddItem_SameSkuDifferentPrice_UsesLatestPrice()
    {
        _cart.AddItem("ABC", 2, 5m);
        _cart.AddItem("ABC", 1, 8m);

        // 2 + 1 = 3 quantity at new price 8
        Assert.AreEqual(24m, _cart.CalculateTotal());
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    [DataRow("   ")]
    public void AddItem_InvalidSku_ThrowsArgumentException(string? sku)
    {
        Assert.ThrowsException<ArgumentException>(() => _cart.AddItem(sku!, 1, 10m));
    }

    [TestMethod]
    [DataRow(0)]
    [DataRow(-1)]
    public void AddItem_InvalidQuantity_ThrowsArgumentOutOfRangeException(int qty)
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(() => _cart.AddItem("SKU", qty, 10m));
    }

    [TestMethod]
    public void AddItem_NegativePrice_ThrowsArgumentOutOfRangeException()
    {
        Assert.ThrowsException<ArgumentOutOfRangeException>(() => _cart.AddItem("SKU", 1, -1m));
    }

    [TestMethod]
    public void AddItem_ZeroPrice_Succeeds()
    {
        _cart.AddItem("FREE", 1, 0m);
        Assert.AreEqual(0m, _cart.CalculateTotal());
    }

    // --- RemoveItem Tests ---

    [TestMethod]
    public void RemoveItem_ExistingItem_RemovesFromCart()
    {
        _cart.AddItem("SKU-1", 2, 10m);
        _cart.AddItem("SKU-2", 1, 5m);

        _cart.RemoveItem("SKU-1");

        Assert.AreEqual(5m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void RemoveItem_NonExistentSku_ThrowsKeyNotFoundException()
    {
        Assert.ThrowsException<KeyNotFoundException>(() => _cart.RemoveItem("MISSING"));
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    [DataRow("  ")]
    public void RemoveItem_InvalidSku_ThrowsArgumentException(string? sku)
    {
        Assert.ThrowsException<ArgumentException>(() => _cart.RemoveItem(sku!));
    }

    // --- CalculateTotal Tests ---

    [TestMethod]
    public void CalculateTotal_EmptyCart_ReturnsZero()
    {
        Assert.AreEqual(0m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void CalculateTotal_MultipleItems_ReturnsSumOfLineItems()
    {
        _cart.AddItem("A", 2, 10m);
        _cart.AddItem("B", 3, 5m);

        Assert.AreEqual(35m, _cart.CalculateTotal());
    }

    // --- ApplyCoupon Tests ---

    [TestMethod]
    [DataRow("SAVE10", 90.0)]
    [DataRow("SAVE20", 80.0)]
    [DataRow("HALF", 50.0)]
    public void ApplyCoupon_ValidCode_ReducesTotal(string code, double expectedTotal)
    {
        _cart.AddItem("ITEM", 1, 100m);
        _cart.ApplyCoupon(code);

        Assert.AreEqual((decimal)expectedTotal, _cart.CalculateTotal());
    }

    [TestMethod]
    public void ApplyCoupon_CaseInsensitive_Works()
    {
        _cart.AddItem("ITEM", 1, 100m);
        _cart.ApplyCoupon("save10");

        Assert.AreEqual(90m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void ApplyCoupon_InvalidCode_ThrowsArgumentException()
    {
        Assert.ThrowsException<ArgumentException>(() => _cart.ApplyCoupon("BOGUS"));
    }

    [TestMethod]
    [DataRow(null)]
    [DataRow("")]
    [DataRow("  ")]
    public void ApplyCoupon_NullOrEmpty_ThrowsArgumentException(string? code)
    {
        Assert.ThrowsException<ArgumentException>(() => _cart.ApplyCoupon(code!));
    }

    [TestMethod]
    public void ApplyCoupon_AppliedAfterItems_AffectsTotal()
    {
        _cart.AddItem("X", 4, 25m); // subtotal 100
        _cart.ApplyCoupon("SAVE20");

        Assert.AreEqual(80m, _cart.CalculateTotal());
    }

    [TestMethod]
    public void ApplyCoupon_ReplacedByNewCoupon_UsesLatest()
    {
        _cart.AddItem("X", 1, 100m);
        _cart.ApplyCoupon("SAVE10");
        _cart.ApplyCoupon("HALF");

        Assert.AreEqual(50m, _cart.CalculateTotal());
    }
}

